"use client";
import { ArtemisScope } from "./artemis-scope";
import View0 from "./components/comparison/variants/04-before-after";
export interface ArtemisComparisonBeforeAfterProps { className?: string;  }
export function ArtemisComparisonBeforeAfter({ className }: ArtemisComparisonBeforeAfterProps) {return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View0/></div></ArtemisScope>;}

"use client";
// @zeus-internal
import { motion, useReducedMotion, type Transition } from "motion/react";
import type { ReactNode } from "react";
import { ARTEMIS_EASE_OUT } from "../../../lib/ease";
type Step = {
    title: string;
    description: string;
};
type Side = {
    key: "before" | "after";
    label: string;
    title: string;
    footer: string;
    icon: ReactNode;
    marker: ReactNode;
    steps: readonly Step[];
};
const SVG_PROPS = {
    xmlns: "http://www.w3.org/2000/svg",
    width: "24",
    height: "24",
    viewBox: "0 0 24 24",
    fill: "none",
    stroke: "currentColor",
    strokeWidth: "2",
    strokeLinecap: "round",
    strokeLinejoin: "round",
    "aria-hidden": "true",
} as const;
const SIDES: readonly Side[] = [
    {
        key: "before",
        label: "Before",
        title: "The scattered approach",
        footer: "Your team holds everything together.",
        icon: (<svg {...SVG_PROPS} className="art:lucide art:lucide-layers art:size-5">
        <path d="M12.83 2.18a2 2 0 0 0-1.66 0L2.6 6.08a1 1 0 0 0 0 1.83l8.58 3.91a2 2 0 0 0 1.66 0l8.58-3.9a1 1 0 0 0 0-1.83z"/>
        <path d="M2 12a1 1 0 0 0 .58.91l8.6 3.91a2 2 0 0 0 1.65 0l8.58-3.9A1 1 0 0 0 22 12"/>
        <path d="M2 17a1 1 0 0 0 .58.91l8.6 3.91a2 2 0 0 0 1.65 0l8.58-3.9A1 1 0 0 0 22 17"/>
      </svg>),
        marker: (<svg {...SVG_PROPS} className="art:lucide art:lucide-minus art:size-3">
        <path d="M5 12h14"/>
      </svg>),
        steps: [
            { title: "Requests everywhere", description: "Check your inbox, chat, and spreadsheets for the full picture." },
            { title: "Another handoff", description: "Ask around to find out who has time to take it on." },
            { title: "Chasing an update", description: "Send a follow-up just to learn where things stand." },
            { title: "Rebuild the context", description: "Dig through old threads when the same question comes up." },
        ],
    },
    {
        key: "after",
        label: "After",
        title: "A connected workspace",
        footer: "Your workspace keeps everyone together.",
        icon: (<svg {...SVG_PROPS} className="art:lucide art:lucide-route art:size-5">
        <circle cx="6" cy="19" r="3"/>
        <path d="M9 19h8.5a3.5 3.5 0 0 0 0-7h-11a3.5 3.5 0 0 1 0-7H15"/>
        <circle cx="18" cy="5" r="3"/>
      </svg>),
        marker: (<svg {...SVG_PROPS} className="art:lucide art:lucide-check art:size-3">
        <path d="M20 6 9 17l-5-5"/>
      </svg>),
        steps: [
            { title: "One place to start", description: "Every request arrives in a shared, organized queue." },
            { title: "A clear next step", description: "Assign an owner and keep the context with the work." },
            { title: "Progress you can see", description: "Follow each task from its first step to the finish." },
            { title: "Keep what you learn", description: "Turn completed work into a useful reference for next time." },
        ],
    },
];
const CARD_DURATION = 0.4;
const CARD_STAGGER = 0.1;
const ROW_DURATION = 0.3;
const ROW_STAGGER = 0.05;
const INSTANT: Transition = { duration: 0 };
export default function ComparisonBeforeAfter() {
    const reduce = useReducedMotion() === true;
    return (<>
      <section className="art:w-full art:bg-background art:px-4 art:py-20 art:text-foreground art:@min-[640px]/artemis:px-8 art:@min-[640px]/artemis:py-24">
        <div className="art:mx-auto art:max-w-5xl">
          <div className="art:max-w-2xl">
            <p className="art:text-sm art:font-medium art:text-muted-foreground">
              {"A better everyday workflow"}
            </p>
            <h2 className="art:mt-4 art:text-balance art:text-4xl art:font-medium art:tracking-tight">
              {"Less chasing. More doing."}
            </h2>
            <p className="art:mt-5 art:max-w-xl art:text-pretty art:text-sm art:leading-6 art:text-muted-foreground art:@min-[640px]/artemis:text-base">
              {"See what changes when your team's work has a place to come together."}
            </p>
          </div>
          <div className="art:relative art:mt-10 art:grid art:gap-4 art:@min-[768px]/artemis:grid-cols-2 art:@min-[768px]/artemis:gap-8">
            {SIDES.map((side, sideIndex) => (<motion.article key={side.key} className="art:flex art:flex-col art:rounded-3xl art:border art:border-border art:bg-background art:p-6 art:@min-[640px]/artemis:p-8" initial={{ opacity: 0, y: 12 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true, amount: 0.15 }} transition={reduce ? INSTANT : { duration: CARD_DURATION, ease: ARTEMIS_EASE_OUT, delay: sideIndex * CARD_STAGGER }}>
                <div className="art:mb-7 art:flex art:items-center art:justify-between art:gap-4">
                  <span className="art:flex art:size-10 art:items-center art:justify-center art:rounded-full art:bg-muted">
                    {side.icon}
                  </span>
                  <span className="art:text-xs art:font-medium art:text-muted-foreground">
                    {side.label}
                  </span>
                </div>
                <h3 className="art:text-xl art:font-medium">
                  {side.title}
                </h3>
                <ol className="art:my-8 art:flex-1 art:space-y-7">
                  {side.steps.map((step, stepIndex) => (<motion.li key={step.title} className="art:flex art:gap-3" initial={{ opacity: 0, x: side.key === "after" ? -6 : 0 }} whileInView={{ opacity: 1, x: 0 }} viewport={{ once: true, amount: 0.5 }} transition={reduce ? INSTANT : { duration: ROW_DURATION, ease: ARTEMIS_EASE_OUT, delay: stepIndex * ROW_STAGGER }}>
                      <span className="art:mt-0.5 art:flex art:size-5 art:shrink-0 art:items-center art:justify-center art:rounded-full art:bg-muted art:text-muted-foreground">
                        {side.marker}
                      </span>
                      <div>
                        <p className="art:text-sm art:font-medium">
                          {step.title}
                        </p>
                        <p className="art:mt-1.5 art:text-sm art:leading-6 art:text-muted-foreground">
                          {step.description}
                        </p>
                      </div>
                    </motion.li>))}
                </ol>
                <p className="art:border-t art:border-border art:pt-5 art:text-sm art:font-medium art:leading-6">
                  {side.footer}
                </p>
              </motion.article>))}
            <span aria-hidden="true" className="art:pointer-events-none art:absolute art:left-1/2 art:top-16 art:hidden art:size-10 art:-translate-x-1/2 art:items-center art:justify-center art:rounded-full art:border art:border-border art:bg-background art:@min-[768px]/artemis:flex">
              <svg {...SVG_PROPS} className="art:lucide art:lucide-arrow-right art:size-4">
                <path d="M5 12h14"/>
                <path d="m12 5 7 7-7 7"/>
              </svg>
            </span>
          </div>
        </div>
      </section>
    </>);
}
